  KEY `invoice_items_account_id` (`account_id`),
  KEY `invoice_items_linked_item_id` (`linked_item_id`),
  KEY `invoice_items_tenant_account_record_id` (`tenant_record_id`,`account_record_id`)
) ENGINE=InnoDB AUTO_INCREMENT=239 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;
