  `updated_by` varchar(50) NOT NULL,
  `updated_date` datetime NOT NULL,
  `account_record_id` bigint(20) unsigned NOT NULL,
  `tenant_record_id` bigint(20) unsigned NOT NULL DEFAULT 0,
